    // Compartir
    "Tu enlace": ["Your link", "Seu link", "Il tuo link"],
    "Copiar enlace": ["Copy link", "Copiar link", "Copia link"],
    "Ponlo en la biografía de tu Instagram, en tus estados de WhatsApp y en tus publicaciones.": ["Put it in your Instagram bio, your WhatsApp status and your posts.", "Coloque na bio do Instagram, nos status do WhatsApp e nas suas publicações.", "Mettilo nella bio di Instagram, negli stati di WhatsApp e nei tuoi post."],
    "Así se ve en WhatsApp": ["How it looks on WhatsApp", "Como aparece no WhatsApp", "Come appare su WhatsApp"],
    "Cuando mandas tu enlace, sale esta tarjeta con tu nombre, tu logo, una foto y tus colores. Se actualiza cada vez que guardas.": ["When you send your link, this card shows with your name, logo, a photo and your colors. It updates every time you save.", "Quando você envia seu link, aparece este cartão com seu nome, logo, uma foto e suas cores. Atualiza sempre que você salva.", "Quando invii il link, appare questa scheda con nome, logo, una foto e i tuoi colori. Si aggiorna ogni volta che salvi."],
    "Tienes cambios sin guardar. Tus clientes ven la tarjeta nueva cuando guardas.": ["You have unsaved changes. Your customers see the new card when you save.", "Você tem alterações não salvas. Seus clientes veem o cartão novo quando você salva.", "Hai modifiche non salvate. I clienti vedono la scheda nuova quando salvi."],
    "Código QR": ["QR code", "Código QR", "Codice QR"],
    "Código QR de tu página": ["Your page's QR code", "Código QR da sua página", "Codice QR della tua pagina"],
    "Imprímelo y ponlo en tus mesas, el mostrador, tus bolsas o tus volantes. Al escanearlo con la cámara, abren tu página.": ["Print it and put it on your tables, counter, bags or flyers. Scanning it with the camera opens your page.", "Imprima e coloque nas mesas, no balcão, nas sacolas ou nos panfletos. Ao escanear com a câmera, abrem sua página.", "Stampalo e mettilo sui tavoli, sul bancone, sulle buste o sui volantini. Scansionandolo con la fotocamera si apre la tua pagina."],
    "Descargar cartel para imprimir": ["Download printable poster", "Baixar cartaz para imprimir", "Scarica il cartello da stampare"],
    "Descargar solo el código": ["Download the code only", "Baixar só o código", "Scarica solo il codice"],
    "El cartel trae tu nombre, tu logo y el código listo para imprimir en media hoja.": ["The poster has your name, logo and the code, ready to print on half a sheet.", "O cartaz traz seu nome, logo e o código pronto para imprimir em meia folha.", "Il cartello ha il tuo nome, il logo e il codice, pronto da stampare su mezzo foglio."],
    "Preparando": ["Preparing", "Preparando", "Preparazione"],
    "Preparando la vista": ["Preparing the preview", "Preparando a prévia", "Preparazione dell'anteprima"],
    "No se pudo preparar el cartel. Prueba de nuevo.": ["The poster couldn't be prepared. Try again.", "Não foi possível preparar o cartaz. Tente de novo.", "Impossibile preparare il cartello. Riprova."],

    // Mis páginas
    "Tus páginas": ["Your pages", "Suas páginas", "Le tue pagine"],
    "Tu página": ["Your page", "Sua página", "La tua pagina"],
