    "Ej: 004512": ["e.g. 004512", "Ex.: 004512", "Es.: 004512"],
    "Captura o comprobante": ["Screenshot or receipt", "Comprovante", "Screenshot o ricevuta"],
    "Foto o PDF. Opcional si pusiste la referencia.": ["Photo or PDF. Optional if you entered the reference.", "Foto ou PDF. Opcional se colocou a referência.", "Foto o PDF. Facoltativo se hai messo il riferimento."],
    "Enviar reporte de pago": ["Send payment report", "Enviar informe de pagamento", "Invia segnalazione di pagamento"],
    "Otro": ["Other", "Outro", "Altro"],
